css:
:root{
  --red:#FF0000;
  --red-hover:#582929;
  --red-ink:#D50000;
  --black:#141416;
  --charcoal:#1E1E20;
  --charcoal-900:#0E0E10;
  --ink:#2C2C2C;
  --muted:#5C5C5C;
  --bg:#FFFFFF;
  --bg-alt:#F3F3F3;
  --line:#E6E6E6;
  --gold:#F5A623;
  --ok:#1E7B45;
  --radius:14px;
  --shadow:0 12px 34px rgba(20,20,22,.12);
  --shadow-sm:0 4px 14px rgba(20,20,22,.08);
  --container:1200px;
  --font:'Average Sans',system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
  --font-head:'Lexend Deca',system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
}
.mi-loc *{box-sizing:border-box}
.mi-loc{scroll-behavior:smooth}
.mi-loc{margin:0;font-family:var(--font);color:var(--ink);background:var(--bg);line-height:1.62;font-size:17px;-webkit-font-smoothing:antialiased}
.mi-loc h1,.mi-loc h2,.mi-loc h3,.mi-loc h4{color:var(--black);line-height:1.16;margin:0 0 .5em;font-weight:600;letter-spacing:-.01em;font-family:var(--font-head)}
.mi-loc .btn,.mi-loc .nav-links>li>a,.mi-loc .nav-phone,.mi-loc .eyebrow,.mi-loc .field label,.mi-loc .card h3,.mi-loc .step h3,.mi-loc .pillar h3,.mi-loc .review .rname,.mi-loc .faq summary,.mi-loc .partner-chip,.mi-loc footer.site h4,.mi-loc .card-link,.mi-loc .topbar,.mi-loc .trustbar .ti,.mi-loc .rating-summary .score{font-family:var(--font-head)}
.mi-loc h1{font-size:clamp(2rem,4.6vw,3.3rem)}
.mi-loc h2{font-size:clamp(1.6rem,3.2vw,2.4rem)}
.mi-loc h3{font-size:1.24rem}
.mi-loc p{margin:0 0 1rem}
.mi-loc a{color:var(--red-ink)}
.mi-loc img{max-width:100%;display:block}
.mi-loc .container{max-width:var(--container);margin:0 auto;padding:0 22px}
.mi-loc .eyebrow{display:inline-flex;align-items:center;gap:.5rem;text-transform:uppercase;letter-spacing:.12em;font-size:.78rem;font-weight:800;color:var(--red);margin-bottom:.7rem}
.mi-loc .eyebrow::before{content:"";width:26px;height:4px;border-radius:3px;background:var(--red)}
.mi-loc .center{text-align:center}
.mi-loc .center .eyebrow{justify-content:center}
.mi-loc .lead{font-size:1.14rem;color:var(--muted)}
.mi-loc .btn{display:inline-flex;align-items:center;gap:.55rem;font-weight:800;font-size:1.04rem;padding:.95rem 1.65rem;border-radius:999px;text-decoration:none;cursor:pointer;border:2px solid transparent;transition:transform .12s ease,background .15s ease}
.mi-loc .btn:focus-visible{outline:3px solid #ffb3b3;outline-offset:2px}
.mi-loc .btn-primary{background:var(--red);color:#fff}
.mi-loc .btn-primary:hover{background:var(--red-hover);transform:translateY(-1px)}
.mi-loc .btn-dark{background:var(--black);color:#fff}
.mi-loc .btn-dark:hover{background:#000;transform:translateY(-1px)}
.mi-loc .btn-ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.mi-loc .btn-ghost:hover{background:rgba(255,255,255,.12)}
.mi-loc .btn-outline{background:transparent;color:var(--black);border-color:var(--black)}
.mi-loc .btn-outline:hover{background:var(--black);color:#fff}
.mi-loc .btn-lg{padding:1.05rem 1.95rem;font-size:1.1rem}
.mi-loc .skip{position:absolute;left:-999px;top:0;background:#fff;color:var(--black);padding:.7rem 1.1rem;z-index:2000;border-radius:0 0 8px 0;font-weight:700}
.mi-loc .skip:focus{left:0}
.mi-loc .topbar{background:var(--black);color:#e7e7e9;font-size:.86rem}
.mi-loc .topbar .container{display:flex;justify-content:space-between;align-items:center;gap:1rem;min-height:38px;flex-wrap:wrap}
.mi-loc .topbar a{color:#fff;text-decoration:none}
.mi-loc .topbar .tb-left i{color:var(--red);margin-right:.35rem}
.mi-loc .topbar .tb-right{display:flex;gap:1.15rem;align-items:center}
.mi-loc .topbar .tb-right i{color:var(--red);margin-right:.3rem}
.mi-loc .topbar .sep{opacity:.35}
.mi-loc header.site{position:sticky;top:0;z-index:1000;background:#fff;border-bottom:1px solid #ececec;box-shadow:0 2px 12px rgba(20,20,22,.06)}
.mi-loc .nav{display:flex;align-items:center;justify-content:space-between;gap:1rem;min-height:76px}
.mi-loc .brand{display:flex;align-items:center;text-decoration:none}
.mi-loc .brand img{height:52px;width:auto}
.mi-loc .nav-links{display:flex;align-items:center;gap:1.35rem;list-style:none;margin:0;padding:0}
.mi-loc .nav-links > li > a{color:var(--black);text-decoration:none;font-weight:700;font-size:.98rem;padding:.4rem 0}
.mi-loc .nav-links > li > a:hover{color:var(--red)}
.mi-loc .has-menu{position:relative}
.mi-loc .has-menu > a::after{content:"\f107";font-family:"Font Awesome 6 Free";font-weight:900;font-size:.75rem;margin-left:.35rem}
.mi-loc .submenu{position:absolute;top:calc(100% + 8px);left:0;background:#fff;border:1px solid #ececec;border-radius:12px;box-shadow:var(--shadow);padding:.5rem;min-width:250px;display:none;grid-template-columns:1fr 1fr;gap:.1rem;z-index:50}
.mi-loc .submenu a{display:block;padding:.5rem .7rem;border-radius:8px;text-decoration:none;color:var(--ink);font-size:.92rem;font-weight:600}
.mi-loc .submenu a:hover{background:#fff0f0;color:var(--red)}
.mi-loc .has-menu:hover .submenu,.mi-loc .has-menu:focus-within .submenu{display:grid}
.mi-loc .nav-cta{display:flex;align-items:center;gap:.7rem}
.mi-loc .nav-phone{display:inline-flex;align-items:center;gap:.5rem;font-weight:800;color:#fff;background:var(--red);text-decoration:none;font-size:1rem;padding:.6rem 1.05rem;border-radius:999px}
.mi-loc .nav-phone:hover{background:var(--red-hover)}
.mi-loc .hamburger{display:none;background:var(--black);color:#fff;border:0;width:46px;height:46px;border-radius:10px;font-size:1.2rem;cursor:pointer}
.mi-loc .hero{background:var(--charcoal);color:#f2f2f3;position:relative;overflow:hidden}
.mi-loc .hero .container{display:grid;grid-template-columns:1.12fr .88fr;gap:2.4rem;padding-top:3.2rem;padding-bottom:3.4rem;align-items:center;position:relative;z-index:2}
.mi-loc .hero .breadcrumb{font-size:.85rem;color:#b9b9bd;margin-bottom:1rem}
.mi-loc .hero .breadcrumb a{color:#fff;text-decoration:none}
.mi-loc .hero .breadcrumb a:hover{text-decoration:underline}
.mi-loc .hero h1{color:#fff;margin-bottom:.7rem}
.mi-loc .hero .subhead{font-size:1.16rem;color:#d4d4d7;max-width:40ch;margin-bottom:1.4rem}
.mi-loc .eeat{display:flex;flex-wrap:wrap;gap:.55rem;margin:0 0 1.6rem;padding:0;list-style:none}
.mi-loc .eeat li{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);padding:.5rem .85rem;border-radius:999px;font-size:.9rem;font-weight:700;color:#fff}
.mi-loc .eeat li i{color:var(--red)}
.mi-loc .eeat li .stars{color:var(--gold)}
.mi-loc .hero-actions{display:flex;gap:.8rem;flex-wrap:wrap;align-items:center}
.mi-loc .trust-inline{margin-top:1.4rem;font-size:.9rem;color:#b9b9bd;display:flex;align-items:center;gap:.5rem}
.mi-loc .trust-inline i{color:var(--red)}
.mi-loc .splash{position:absolute;right:-6%;top:50%;transform:translateY(-50%);width:60%;max-width:760px;z-index:1;opacity:.95;pointer-events:none}
.mi-loc .hero-media{position:relative;z-index:2}
.mi-loc .hero-media .imgph{min-height:360px;border-radius:230px 230px 18px 18px;background:repeating-linear-gradient(135deg,rgba(255,255,255,.10) 0 14px,rgba(255,255,255,.04) 14px 28px);border:2px dashed rgba(255,255,255,.4);color:#fff}
.mi-loc .hero-media .imgph .ph-meta{color:#d9d9dc}
.mi-loc .trustbar{background:#fff;border-bottom:1px solid #efefef}
.mi-loc .trustbar .container{display:flex;flex-wrap:wrap;justify-content:space-between;gap:1rem;padding:1.1rem 22px}
.mi-loc .trustbar .ti{display:flex;align-items:center;gap:.6rem;font-weight:700;color:var(--black);font-size:.95rem}
.mi-loc .trustbar .ti i{color:var(--red);font-size:1.15rem}
.mi-loc .trustbar .ti .stars{color:var(--gold)}
.mi-loc section{padding:4rem 0}
.mi-loc .section-alt{background:var(--bg-alt)}
.mi-loc .section-dark{background:var(--charcoal);color:#dcdcde;position:relative;overflow:hidden}
.mi-loc .section-dark h2,.mi-loc .section-dark h3{color:#fff}
.mi-loc .section-dark .eyebrow{color:#ff6a6a}
.mi-loc .section-dark .eyebrow::before{background:var(--red)}
.mi-loc .section-head{max-width:780px;margin:0 auto 2.4rem;text-align:center}
.mi-loc .split{display:grid;grid-template-columns:1fr 1fr;gap:2.6rem;align-items:center}
.mi-loc .split.reverse .split-media{order:2}
.mi-loc .prose h2{margin-bottom:.7rem}
.mi-loc .ticklist{list-style:none;padding:0;margin:1rem 0 0;display:grid;gap:.6rem}
.mi-loc .ticklist li{display:flex;gap:.65rem;align-items:flex-start;font-weight:600;color:var(--ink)}
.mi-loc .ticklist li i{color:var(--red);margin-top:.28rem}
.mi-loc .imgph{position:relative;border-radius:var(--radius);overflow:hidden;background:repeating-linear-gradient(135deg,#f0f0f0 0 14px,#e7e7e7 14px 28px);border:2px dashed #c2c2c2;display:flex;align-items:center;justify-content:center;min-height:260px;color:var(--black)}
.mi-loc .imgph .ph-inner{text-align:center;padding:1rem;max-width:90%}
.mi-loc .imgph .ph-tag{display:inline-block;background:var(--red);color:#fff;font-size:.7rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase;padding:.3rem .6rem;border-radius:6px;margin-bottom:.55rem}
.mi-loc .imgph .ph-purpose{font-weight:700;font-size:.95rem;margin-bottom:.25rem}
.mi-loc .imgph .ph-meta{font-size:.78rem;color:var(--muted);font-weight:600}
.mi-loc .imgph.tall{min-height:100%}
.mi-loc .cards{display:grid;grid-template-columns:repeat(4,1fr);gap:1.1rem}
.mi-loc .card{background:#fff;border:1px solid #ececec;border-radius:var(--radius);padding:1.4rem 1.25rem;box-shadow:var(--shadow-sm);transition:transform .14s ease,box-shadow .14s ease,border-color .14s ease;display:flex;flex-direction:column}
.mi-loc .card:hover{transform:translateY(-4px);box-shadow:var(--shadow);border-color:#ffc9c9}
.mi-loc .card .ic{width:52px;height:52px;border-radius:12px;background:#fff0f0;color:var(--red);display:flex;align-items:center;justify-content:center;font-size:1.35rem;margin-bottom:.9rem}
.mi-loc .card h3{font-size:1.1rem;margin-bottom:.4rem}
.mi-loc .card p{font-size:.93rem;color:var(--muted);margin-bottom:1rem;flex:1}
.mi-loc .card .card-link{font-weight:800;color:var(--red-ink);text-decoration:none;font-size:.92rem;display:inline-flex;align-items:center;gap:.4rem}
.mi-loc .card .card-link:hover{gap:.6rem}
.mi-loc .pillars{display:grid;grid-template-columns:repeat(3,1fr);gap:1.4rem}
.mi-loc .pillar{background:#fff;border-radius:var(--radius);padding:1.6rem;box-shadow:var(--shadow-sm);border-top:4px solid var(--red)}
.mi-loc .pillar i{font-size:1.6rem;color:var(--red);margin-bottom:.6rem}
.mi-loc .pillar h3{font-size:1.14rem}
.mi-loc .pillar p{font-size:.95rem;color:var(--muted);margin:0}
.mi-loc .steps{display:grid;grid-template-columns:repeat(4,1fr);gap:1.2rem}
.mi-loc .step{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.14);border-radius:var(--radius);padding:1.5rem 1.3rem}
.mi-loc .step .num{width:44px;height:44px;border-radius:50%;background:var(--red);color:#fff;font-weight:800;font-size:1.15rem;display:flex;align-items:center;justify-content:center;margin-bottom:.8rem}
.mi-loc .step h3{color:#fff;font-size:1.08rem;margin-bottom:.3rem}
.mi-loc .step p{color:#c7c7ca;font-size:.9rem;margin:0}
.mi-loc .coverage{background:#fff;border:1px solid #ececec;border-radius:var(--radius);padding:1.8rem;box-shadow:var(--shadow-sm)}
.mi-loc .suburb-grid{columns:4;column-gap:1.4rem;margin:1rem 0 0}
.mi-loc .suburb-grid span{display:flex;align-items:center;gap:.5rem;padding:.28rem 0;font-weight:600;color:var(--ink);font-size:.95rem;break-inside:avoid}
.mi-loc .suburb-grid span i{color:var(--red);font-size:.7rem}
.mi-loc .coverage-note{margin-top:1.3rem;padding:1rem 1.15rem;background:#fff0f0;border:1px solid #ffd4d4;border-radius:10px;font-weight:600;color:var(--black);display:flex;align-items:center;gap:.7rem;flex-wrap:wrap}
.mi-loc .coverage-note i{color:var(--red)}
.mi-loc .partners{display:flex;flex-wrap:wrap;gap:1rem;justify-content:center;align-items:center;margin-top:1.5rem}
.mi-loc .partner-chip{background:#fff;border:1px solid #e6e6e6;border-radius:10px;padding:.75rem 1.3rem;font-weight:800;color:var(--black);box-shadow:var(--shadow-sm)}
.mi-loc .rating-summary{display:flex;align-items:center;gap:1.1rem;justify-content:center;flex-wrap:wrap;margin-bottom:1.8rem}
.mi-loc .rating-summary .gwrap{display:flex;align-items:center;gap:.8rem;background:#fff;border:1px solid #ececec;border-radius:14px;padding:1rem 1.4rem;box-shadow:var(--shadow-sm)}
.mi-loc .rating-summary .score{font-size:2.4rem;font-weight:800;color:var(--black);line-height:1}
.mi-loc .rating-summary .stars{color:var(--gold);font-size:1.15rem}
.mi-loc .rating-summary .rs-meta{font-size:.9rem;color:var(--muted);font-weight:600}
.mi-loc .review-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1.2rem;max-width:900px;margin:0 auto}
.mi-loc .review{background:#fff;border:1px solid #ececec;border-radius:var(--radius);padding:1.5rem;box-shadow:var(--shadow-sm)}
.mi-loc .review .rtop{display:flex;justify-content:space-between;align-items:center;margin-bottom:.6rem}
.mi-loc .review .stars{color:var(--gold)}
.mi-loc .review .gicon{color:#4285F4;font-size:1.1rem}
.mi-loc .review .rtext{color:var(--ink);font-size:.98rem}
.mi-loc .review .rname{margin-top:.9rem;font-weight:800;color:var(--black);font-size:.92rem}
.mi-loc .review .rname span{display:block;font-weight:600;color:var(--muted);font-size:.8rem}
.mi-loc .faq{max-width:860px;margin:0 auto}
.mi-loc .faq details{background:#fff;border:1px solid #ececec;border-radius:12px;margin-bottom:.8rem;box-shadow:var(--shadow-sm);overflow:hidden}
.mi-loc .faq summary{cursor:pointer;padding:1.1rem 1.3rem;font-weight:800;color:var(--black);list-style:none;display:flex;justify-content:space-between;align-items:center;gap:1rem;font-size:1.02rem}
.mi-loc .faq summary::-webkit-details-marker{display:none}
.mi-loc .faq summary::after{content:"\f067";font-family:"Font Awesome 6 Free";font-weight:900;color:var(--red);font-size:.85rem;flex:none}
.mi-loc .faq details[open] summary::after{content:"\f068"}
.mi-loc .faq .faq-body{padding:0 1.3rem 1.2rem;color:var(--muted)}
.mi-loc .cta-band{background:var(--charcoal);color:#fff;text-align:center;position:relative;overflow:hidden}
.mi-loc .cta-band h2{color:#fff}
.mi-loc .cta-band p{color:#d4d4d7;max-width:60ch;margin:0 auto 1.6rem;font-size:1.12rem}
.mi-loc .cta-actions{display:flex;gap:.9rem;justify-content:center;flex-wrap:wrap;position:relative;z-index:2}
.mi-loc .cta-band .splash{opacity:.9}
.mi-loc footer.site{background:var(--charcoal-900);color:#b4b4b8;font-size:.93rem}
.mi-loc .footer-top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.1fr;gap:2rem;padding:3.2rem 0 2.4rem}
.mi-loc footer.site h4{color:#fff;font-size:1rem;margin-bottom:1rem;text-transform:uppercase;letter-spacing:.06em}
.mi-loc footer.site a{color:#c9c9cc;text-decoration:none}
.mi-loc footer.site a:hover{color:#fff;text-decoration:underline}
.mi-loc .footer-brand .logo-plate{display:inline-block;background:#fff;padding:.7rem .9rem;border-radius:12px;margin-bottom:1rem}
.mi-loc .footer-brand .logo-plate img{height:50px;width:auto}
.mi-loc .footer-brand p{color:#9c9ca0;font-size:.9rem;max-width:34ch}
.mi-loc .f-contact{padding:0;margin:0}
.mi-loc .f-contact li{display:flex;gap:.6rem;align-items:flex-start;margin-bottom:.6rem;list-style:none}
.mi-loc .f-contact i{color:var(--red);margin-top:.25rem;width:16px;text-align:center}
.mi-loc .f-list{list-style:none;padding:0;margin:0;display:grid;gap:.5rem}
.mi-loc .socials{display:flex;gap:.55rem;margin-top:1.1rem;flex-wrap:wrap}
.mi-loc .socials a{width:40px;height:40px;border-radius:9px;background:rgba(255,255,255,.08);color:#fff;display:flex;align-items:center;justify-content:center;font-size:1.05rem;transition:background .15s ease}
.mi-loc .socials a:hover{background:var(--red)}
.mi-loc .footer-bottom{border-top:1px solid rgba(255,255,255,.12);padding:1.3rem 0;display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap;font-size:.85rem;color:#8a8a8e}
.mi-loc .footer-bottom a{color:#b4b4b8}
.mi-loc .quote-card{background:#fff;color:var(--ink);border-radius:18px;box-shadow:var(--shadow);padding:1.5rem;border:1px solid #ececec}
.mi-loc .quote-card h3{font-size:1.35rem;margin-bottom:.25rem}
.mi-loc .quote-card .qc-sub{color:var(--muted);font-size:.92rem;margin-bottom:1rem}
.mi-loc .field{margin-bottom:.7rem}
.mi-loc .field label{display:block;font-size:.82rem;font-weight:700;color:var(--black);margin-bottom:.28rem}
.mi-loc .field label .req{color:var(--red)}
.mi-loc .field input,.mi-loc .field select,.mi-loc .field textarea{width:100%;padding:.72rem .8rem;border:1.5px solid #d8d8d8;border-radius:10px;font-size:.97rem;font-family:inherit;color:var(--ink);background:#fff}
.mi-loc .field input:focus,.mi-loc .field select:focus,.mi-loc .field textarea:focus{outline:0;border-color:var(--red);box-shadow:0 0 0 3px rgba(252,0,0,.14)}
.mi-loc .field textarea{resize:vertical;min-height:64px}
.mi-loc .hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.mi-loc .form-note{font-size:.78rem;color:var(--muted);margin:.5rem 0 0}
.mi-loc .form-status{display:none;margin-top:.7rem;padding:.7rem .8rem;border-radius:8px;font-size:.9rem;font-weight:600}
.mi-loc .form-status.show{display:block}
.mi-loc .form-status.test{background:#fff4e5;border:1px solid #f4c88a;color:#8a5a12}
.mi-loc .imgph .ph-tag,.mi-loc .imgph .ph-meta{display:none}
@media(max-width:1024px){.mi-loc .cards{grid-template-columns:repeat(2,1fr)}
.mi-loc .steps{grid-template-columns:repeat(2,1fr)}
.mi-loc .suburb-grid{columns:3}
.mi-loc .footer-top{grid-template-columns:1fr 1fr}
.mi-loc .hero .container{grid-template-columns:1fr;gap:1.8rem}
.mi-loc .hero-media .imgph{display:none}
.mi-loc .splash{opacity:.5;right:-20%}}
@media(max-width:820px){.mi-loc .nav-links,.mi-loc .nav-phone .np-label{display:none}
.mi-loc .hamburger{display:inline-flex}
.mi-loc .nav-links.open{display:flex;position:absolute;top:76px;left:0;right:0;flex-direction:column;background:#fff;padding:1rem;gap:.2rem;border-bottom:1px solid #ececec;box-shadow:var(--shadow)}
.mi-loc .nav-links.open > li{width:100%}
.mi-loc .nav-links.open > li > a{display:block;padding:.8rem .4rem;border-bottom:1px solid #f2f2f2}
.mi-loc .submenu{position:static;display:grid;box-shadow:none;border:0;padding:.2rem 0 .6rem 1rem;grid-template-columns:1fr}
.mi-loc .has-menu > a::after{display:none}
.mi-loc .split{grid-template-columns:1fr;gap:1.5rem}
.mi-loc .split.reverse .split-media{order:0}
.mi-loc .pillars,.mi-loc .review-grid{grid-template-columns:1fr}
.mi-loc .suburb-grid{columns:2}}
@media(max-width:560px){.mi-loc .cards,.mi-loc .steps,.mi-loc .footer-top{grid-template-columns:1fr}
.mi-loc .topbar .tb-left{display:none}
.mi-loc{font-size:16px}}
@media(prefers-reduced-motion:reduce){.mi-loc *{scroll-behavior:auto!important;transition:none!important;animation:none!important}}
.mi-loc .suburb-grid a{display:flex;align-items:center;gap:.5rem;padding:.28rem 0;font-weight:700;color:var(--red-ink);text-decoration:none;break-inside:avoid;font-size:.95rem}
.mi-loc .suburb-grid a:hover{color:var(--red);text-decoration:underline}
.mi-loc .suburb-grid a i,.mi-loc .suburb-grid span i{color:var(--red);font-size:.7rem}
.mi-loc .also-serve{margin-top:1.1rem;color:var(--muted);font-size:.95rem;line-height:1.7}
.mi-loc .also-serve strong{color:var(--black)}
.mi-loc{width:100vw;max-width:100vw;margin-left:calc(50% - 50vw);overflow-x:clip}
.mi-loc .service-tabs{
  background:#fff;
  border:1px solid #e6e6e6;
  box-shadow:var(--shadow-sm);
}
.mi-loc .service-tabs input[type="radio"]{
  position:absolute;
  opacity:0;
  pointer-events:none;
}
.mi-loc .tab-buttons{
  display:grid;
  grid-template-columns:repeat(3,1fr);
}
.mi-loc .tab-buttons label{
  padding:18px;
  text-align:center;
  background:#f5f5f5;
  color:var(--black);
  font-family:var(--font-head);
  font-size:16px;
  font-weight:700;
  cursor:pointer;
  border-right:1px solid #e6e6e6;
}
.mi-loc .tab-buttons label:last-child{
  border-right:0;
}
.mi-loc .tab-buttons label:hover{
  background:#fff0f0;
  color:var(--red);
}
.mi-loc .tab-panels{
  padding:25px;
}
.mi-loc .tab-panel{
  display:none;
}
.mi-loc #tab-painter:checked ~ .tab-buttons label[for="tab-painter"],
.mi-loc #tab-plastering:checked ~ .tab-buttons label[for="tab-plastering"],
.mi-loc #tab-pressure:checked ~ .tab-buttons label[for="tab-pressure"]{
  background:var(--red);
  color:#fff;
}
.mi-loc #tab-painter:checked ~ .tab-panels .painter-panel,
.mi-loc #tab-plastering:checked ~ .tab-panels .plastering-panel,
.mi-loc #tab-pressure:checked ~ .tab-panels .pressure-panel{
  display:block;
}
@media(max-width:768px){
  .mi-loc .tab-buttons{
    grid-template-columns:1fr;
  }
  .mi-loc .tab-buttons label{
    border-right:0;
    border-bottom:1px solid #e6e6e6;
  }
}
